import React from 'react'; import { FaRocket,FaCode,FaChartLine,FaShieldAlt,FaCheckCircle,FaLock } from 'react-icons/fa'; import './Approach.css';
const items=[['UX-led engineering','We begin with the people using the product, then turn the right experience into dependable technology.',<FaRocket/>],['A shared understanding','We work transparently from discovery through delivery, so decisions stay clear and momentum stays high.',<FaCode/>],['Proven experience','A senior team brings practical judgment to complex decisions, without adding unnecessary process.',<FaChartLine/>],['Security by design','Performance, privacy, and maintainability are considered in every layer of the product.',<FaShieldAlt/>],['Thoughtful code reviews','Small details are reviewed carefully, resulting in a cleaner and more resilient product foundation.',<FaCheckCircle/>],['Quality assurance & testing','We test early and often so the release is confident, stable, and ready for real people.',<FaLock/>]];
const Approach=()=> <section className="approach-section"><span className="mini-rule"/><h2>Our design and<br/><b>development approach</b></h2><div className="approach-grid">{items.map(([title,copy,icon])=><article key={title}><span>{icon}</span><div><h3>{title}</h3><p>{copy}</p></div></article>)}</div></section>;
export default Approach;
